// All aspect items (`AspectXxx` traits + `aspect_xxx_aspect_id` /
// `_get` / `_get_maybe` helpers) live in `crate::r#gen` (build-time
// generated single-file gen.rs). This wildcard re-export predates the
// `no-republishing` rule — keeping it minimizes churn at the many
// existing `crate::builtin::AspectXxx` callsites.
pub(crate) use crate::r#gen::*;
#[allow(unused_imports)]
use {
    crate::langhelp::Unique,
    paste::paste,
};

// `aspect!` macro deleted. All aspect traits + helpers are generated by
// `build.rs::aspects()` into `$OUT_DIR/gen_aspects.rs` (included from
// `crate::eval::aspect::mod`). Add new aspects in `build.rs`.

// `generate_builtin_artifact!` / `generate_builtin_artifact_type!` macros
// removed. Per-type `artifact_id` / `build_artifact` / `build_type_artifact`
// (and `register`) impls are generated by `build.rs::artifact_ids()` into
// `crate::r#gen` and applied directly via `impl <full::type::Path>` blocks.

// `unique!` macro deleted — its only call site was inside `aspect!`, which
// is also gone. Builtins now declare their identity via either:
//   * the `aspect!` replacement in `build.rs::aspects()` (stable per-trait
//     name → `Unique::from_name("aspect:<trait>")`),
//   * named entries in `build.rs::interfaces()` for builtin source-language
//     interfaces, or
//   * direct `Unique::from_name(stable_name)` calls where a one-off id is
//     needed (each call site supplies its own unique string).

/// Parameterless deserializer registered under a builtin artifact id. Reads the
/// artifact's data field and produces either a value (`value_from_serial`) or a
/// type reference (`type_from_serial`), depending on whether the caller is
/// resolving a value-form or a type-form artifact. Implementations that don't
/// support a form return an error from that method.
pub(crate) trait ArtifactBuiltinDeserializer {
    fn value_from_serial(
        &self,
        xx: &crate::langhelp::ExprContext,
        loc: crate::langhelp::QExprId,
        data: &serde_json::Value,
    ) -> crate::langhelp::EvalRes;
    fn type_from_serial(
        &self,
        xx: &crate::langhelp::ExprContext,
        loc: crate::langhelp::QExprId,
        data: &serde_json::Value,
    ) -> crate::langhelp::EResult<(std::rc::Rc<dyn crate::langhelp::Type>, crate::langhelp::Code)>;
}
